package com.sora.splineroads.world;
import com.sora.splineroads.core.*;import com.sora.splineroads.core.RoadGeometry.*;import com.sora.splineroads.core.InterchangePlanner.*;
import java.nio.file.*;import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.nbt.*;
/** Chronological accepted-boundary replay against an actual SPUI snapshot; never infers range from tails. */
public final class SequenceLimit204Validation {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static ListTag tags(List<Node> nodes){var out=new ListTag();for(var n:nodes)out.add(RoadRecord.writeNode(n));return out;}
 static List<Node> read(ListTag tags){return tags.stream().map(v->RoadRecord.readNode((CompoundTag)v)).toList();}
 static List<Node> radius(List<Node> nodes,V center,double radius){return nodes.stream().map(n->{var p=center.add(n.position().sub(center).horizontalUnit().mul(radius));return new Node(new V(p.x(),n.position().y(),p.z()),n.yaw(),n.grade());}).toList();}
 static boolean guarded(CompoundTag t,int i,Node target){try{ContinuousRoads.physicalEnd(t,i,target);return false;}catch(IllegalArgumentException ex){return ex.getMessage().contains("4096");}}
 public static void main(String[]args)throws Exception{
  if(args.length!=1)throw new IllegalArgumentException("Usage: SequenceLimit204Validation <actual-spui-reduced.nbt>");
  var root=NbtIo.readCompressed(Path.of(args[0]).toFile());var saved=root.getCompound("Saved");var before=saved.copy();var data=new RoadData();UUID group=saved.getUUID("Id");data.interchanges.put(group,saved.copy());for(var v:root.getList("Roads",Tag.TAG_COMPOUND))data.index.put(RoadIndex.Built.loading(RoadRecord.load((CompoundTag)v)));for(var v:root.getList("Junctions",Tag.TAG_COMPOUND)){var q=(CompoundTag)v;data.junctions.put(q.getUUID("Id"),q.copy());}
  var current=read(saved.getList("Nodes",Tag.TAG_COMPOUND));V center=ContinuousFit.center(current.toArray(Node[]::new),Interchanges.read(saved.getCompound("Options")));
  var input=saved.copy();ContinuousReclaim.refresh(data,input);InterchangeJunctions.captureEdits(data,group,input);input.put("Options",Interchanges.write(new Options(Preset.DOUBLE_TRUMPET,false,1,96,20,5,1,5,true,false,0,1,5,true,false,0)));
  var far=radius(current,center,900);check(guarded(input,2,far.get(2))&&guarded(input,3,far.get(3)),"original SPUI snapshot retains both proven conservative interior-limit failures");
  // These 620m endpoints are the accepted STACK anchors recorded by world-sequence-d,
  // not a limit inferred from whatever ordinary road happens to exist outside SPUI.
  var stack=radius(current,center,620);var initial=input.copy();initial.put("Nodes",saved.getList("ContinuousLimits",Tag.TAG_COMPOUND).copy());var initialBefore=initial.copy();
  var afterStack=ContinuousRoads.committedLimits(initial,stack);check(read(afterStack).equals(stack),"accepted STACK expansion was not recorded");check(initial.equals(initialBefore),"computing pending commit bounds mutated input");
  var historical=initial.copy();historical.put("Nodes",tags(stack));historical.put("ContinuousLimits",afterStack.copy());var limitsAfterShrink=ContinuousRoads.committedLimits(historical,current);
  check(read(limitsAfterShrink).equals(stack),"compacting to SPUI forgot accepted STACK extent");
  var repairedHistory=input.copy();repairedHistory.put("ContinuousLimits",limitsAfterShrink);var unchanged=repairedHistory.copy();
  for(int i=0;i<4;i++){var end=ContinuousRoads.physicalEnd(repairedHistory,i,far.get(i));var p=stack.get(i).position();check(end.equals(BlockPos.containing(p.x(),p.y(),p.z())),"physical extension did not select actual accepted outer marker "+i);}
  Plan plan;try(var budget=RoadPlanningBudget.open("accepted historical limits double trumpet",120)){plan=Interchanges.plan(repairedHistory);}check(plan.anchors().size()==4&&!plan.legs().isEmpty(),"DOUBLE_TRUMPET failed after correct chronological persistence");
  var command=repairedHistory.copy();command.put("SourceNodes",repairedHistory.getList("Nodes",Tag.TAG_COMPOUND).copy());command.putInt("SourceAxesHash",HostAxes.signature(repairedHistory));command.put("FittedNodes",tags(plan.anchors()));var confirmed=Interchanges.confirmedPlan(repairedHistory,command);check(plan.anchors().equals(confirmed.anchors()),"confirmed DOUBLE_TRUMPET anchors differ");check(plan.legs().size()==confirmed.legs().size(),"confirmed geometry leg count differs");for(int i=0;i<plan.legs().size();i++)check(plan.legs().get(i).mesh().samples().equals(confirmed.legs().get(i).mesh().samples()),"confirmed geometry changed "+i);
  check(repairedHistory.equals(unchanged),"planning persisted bounds early");check(saved.equals(before),"actual evidence descriptor modified");
  var cap=repairedHistory.copy();var capLimits=read(cap.getList("ContinuousLimits",Tag.TAG_COMPOUND));var exact=new ArrayList<>(capLimits);V ray=current.get(1).position().sub(center).horizontalUnit();var capPoint=center.add(ray.mul(4396));exact.set(1,new Node(new V(capPoint.x(),current.get(1).position().y(),capPoint.z()),current.get(1).yaw(),0));cap.put("ContinuousLimits",tags(exact));
  // A known captured road crosses the real limit and ends beyond it. Its distant end
  // must never be promoted to an authorized endpoint by this persistence operation.
  V start=center.add(ray.mul(620)),end=center.add(ray.mul(5100));start=new V(start.x(),current.get(1).position().y(),start.z());end=new V(end.x(),current.get(1).position().y(),end.z());var settings=RoadRecord.readSettings(cap.getCompound("Main1"));var road=new RoadRecord(new UUID(20426,1),saved.getUUID("Owner"),BlockPos.containing(start.x(),start.y(),start.z()),BlockPos.containing(end.x(),end.y(),end.z()),new Node(start,current.get(1).yaw(),0),new Node(end,current.get(1).yaw(),0),settings,false,4).alignment(null,RoadRibbon.mesh(List.of(new Sample(start,ray.left(),0,settings.width()/2),new Sample(end,ray.left(),0,settings.width()/2)),settings));var q=new CompoundTag();q.putInt("Axis",0);q.put("Road",road.header());cap.getList("ContinuousSources",Tag.TAG_COMPOUND).add(q);
  var preserved=ContinuousRoads.committedLimits(cap,current);check(RoadRecord.readNode(preserved.getCompound(1)).equals(exact.get(1)),"real 4096 internal cap changed");cap.put("ContinuousLimits",preserved);V target=center.add(ray.mul(4400));check(guarded(cap,1,new Node(new V(target.x(),current.get(1).position().y(),target.z()),current.get(1).yaw(),0)),"real interior 4096 cap was bypassed");
  var shifted=new ArrayList<>(current);for(int i=2;i<4;i++){var n=shifted.get(i);shifted.set(i,new Node(n.position().add(new V(10,0,0)),n.yaw(),n.grade()));}check(read(ContinuousRoads.committedLimits(historical,shifted)).equals(shifted),"old center granted range to shifted intersection");
  var rotated=new ArrayList<>(current);for(int i=0;i<2;i++){var n=rotated.get(i);var d=n.position().sub(center);var p=center.add(new V(d.x()*Math.cos(.1)-d.z()*Math.sin(.1),d.y(),d.x()*Math.sin(.1)+d.z()*Math.cos(.1)));rotated.set(i,new Node(p,n.yaw()+Math.toDegrees(.1),n.grade()));}var turn=read(ContinuousRoads.committedLimits(historical,rotated));check(turn.get(0).equals(rotated.get(0))&&turn.get(1).equals(rotated.get(1)),"old axis granted range to rotated road");
  var lowered=new ArrayList<>(stack);for(int i=0;i<lowered.size();i++){var n=lowered.get(i);lowered.set(i,new Node(n.position().add(new V(0,1,0)),n.yaw(),n.grade()));}check(read(ContinuousRoads.committedLimits(historical,lowered)).equals(lowered),"same-radius confirmed height was replaced by stale height");
  System.out.println("SEQUENCE_LIMIT204 PASS checks="+checks+" actual SPUI evidence / accepted STACK620->compact->DOUBLE_TRUMPET / fixed confirmation / true4096 guard / center-direction negatives / input unchanged; anchors="+plan.anchors());
 }
}
